import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    N = int(input[0])
    prefix = "Simon says"
    for i in range(1, N + 1):
        line = input[i]
        if line.startswith(prefix):
            print(line[len(prefix):])

if __name__ == "__main__":
    main()
